/* @lc app=leetcode id=1654 lang=kotlin */ class Solution { fun minimumJumps(forbidden: IntArray, a: Int, b: Int, x: Int): Int = forbidden.toSet().let { fb -> (maxOf(x, forbidden.maxOrNull() ?: 0) + a + b).let { lim -> HashSet<Pair<Int, Int>>().also { it.add(0 to 0) }.let { seen -> generateSequence(listOf(0 to 0)) { f -> f.flatMap { (p, bk) -> listOf(p + a to 0, p - b to 1).filter { (q, nb) -> (nb == 0 || bk == 0) && q in 0..lim && q !in fb } }.filter { seen.add(it) }.takeIf { it.isNotEmpty() } }.indexOfFirst { l -> l.any { it.first == x } } } } } }